seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
import random
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return "".join(comp[c] for c in reversed(s))
stops={'TAA','TAG','TGA'}
def longest(s):
    best=0
    for ss in (s,rc(s)):
        for f in range(3):
            start=None
            for j in range(f,len(ss)-2,3):
                c=ss[j:j+3]
                if c=="ATG" and start is None: start=j
                elif c in stops and start is not None:
                    best=max(best,(j-start)//3); start=None
    return best
print("real longest ORF aa:", longest(seq))
random.seed(0)
vals=[longest("".join(random.sample(list(seq),len(seq)))) for _ in range(300)]
vals.sort()
print("shuffled: mean",sum(vals)/len(vals),"median",vals[len(vals)//2],"95pct",vals[int(.95*len(vals))],"max",max(vals))
print("frac >=345:", sum(1 for v in vals if v>=345)/len(vals))
